def transform(grid):
    def cw(a):
        return [list(row) for row in zip(*a[::-1])]
    def ccw(a):
        return [list(row) for row in zip(*a)][::-1]
    def rot180(a):
        return [row[::-1] for row in a[::-1]]

    tiles = [grid, cw(grid), ccw(grid), rot180(grid)]
    out = []
    for i, row in enumerate(grid):
        out.append(row + tiles[1][i])
    for i, row in enumerate(tiles[2]):
        out.append(row + tiles[3][i])
    return out
